// ../es-samples/samples/es2021/logical-assignment.js
function demoLogicalAssignment() {
  let a = 0;
  a ||= 10;
  let b = "hello";
  b &&= b.toUpperCase();
  let c = null;
  c ??= "default";
  return { a, b, c };
}

